第六题（10分）ECF
1.（5 分）以下程序运行时系统调用全部正确执行，buffer.txt 文件的内容为
pekinguniv。请给出代码运行后打印输出的结果，并给出程序运行结束后
buffer.txt文件的内容。
```
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
int main() {
    char c;
    int file1 = open("buffer.txt", O_RDWR);
    int file2;
    read(file1, &c, 1);
    file2 = dup(file1);
    write(file2, &c, 1);
    printf("1 = %c\n", c);
    int pid = fork() ;
    if (pid == 0) {
        read(file1, &c, 1);
        write(file2, &c, 1);
        printf("2 = %c\n", c);
        read(file1, &c, 1);
        printf("3 = %c\n", c);
        close(file1);
        exit(0);
    } else {
        waitpid(pid, NULL, 0);
        close(file2);
        dup2(file1, file2);
        read(file2, &c, 1);
        write(file2, &c, 1);
        printf("4 = %c\n", c);
    }
    return 0;
}
```
19

