        signal(SIGUSR1, handler);
        fd1 = open(fname, O_RDONLY);
        read(fd1, &c1, 1);
        parent = getpid();
        if (fork()) {
                wait();
                fd2 = open(fname, O_RDONLY);
        } else {
                kill(parent, SIGUSR1);
                fd2 = dup(fd1);
        }
        read(fd2, &c2, 1);
        parent = getpid();
        if (fork()) {
                wait();
                fd3 = open(fname, O_RDONLY);
        } else {
                kill(parent, SIGUSR1);
                fd3 = dup(fd2);
        }
        read(fd3, &c3, 1);
        printf("%c %c %c %d\n", c1, c2, c3, counter);
        return 0;
}
